import {
    Table,
    ReferenceColumn,
    SystemClassNameColumn,
    ListColumn,
    GenericColumn,
    StringColumn,
    DateTimeColumn,
    IntegerColumn,
    DurationColumn,
    BooleanColumn,
    GuidColumn,
    DomainPathColumn,
    DueDateColumn,
    DomainIdColumn,
} from '@servicenow/sdk/core'

export const task = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.detail_row': 'short_description',
        'all_tables.display_color': 'priority',
        'all_tables.live_feed': true,
        'all_tables.text_index_translations': true,
        extension_model: 'hierarchy',
        hasListeners: true,
        kagami_csindex_enabled: true,
        largeTable: true,
        reference_index_include: 'active',
    },
    autoNumber: {
        number: 20000,
        prefix: 'TASK',
    },
    display: 'number',
    extensible: true,
    label: 'Task',
    liveFeed: true,
    name: 'task',
    schema: {
        wf_activity: ReferenceColumn({
            active: false,
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'clear',
            label: 'Workflow activity',
            referenceTable: 'wf_activity',
        }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Task type',
            maxLength: 80,
        }),
        business_service: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Service',
            referenceTable: 'cmdb_ci_service',
        }),
        work_notes_list: ListColumn({
            attributes: {
                array: 'denormalized',
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Users interested in work notes',
                    label: 'Work notes list',
                    plural: 'Work notes lists',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        variables: GenericColumn({
            active: false,
            columnType: 'variables',
            label: 'Variables',
        }),
        assignment_group: ReferenceColumn({
            attributes: {
                tree_picker: true,
            },
            label: 'Assignment group',
            referenceTable: 'sys_user_group',
            referenceQual: 'type=null^ORtype=1cb8ab9bff500200158bffffffffff62^EQ',
        }),
        upon_reject: StringColumn({
            default: 'cancel',
            dropdown: 'dropdown_with_none',
            label: 'Upon reject',
        }),
        work_end: DateTimeColumn({
            attributes: {
                sla_closure: true,
                timeDimension: true,
            },
            label: [
                {
                    label: 'Actual end',
                    plural: 'Actual end',
                    language: 'en',
                },
            ],
        }),
        work_start: DateTimeColumn({
            attributes: {
                sla_basis: true,
                timeDimension: true,
            },
            label: [
                {
                    label: 'Actual start',
                    plural: 'Actual start',
                    language: 'en',
                },
            ],
        }),
        rejection_goto: ReferenceColumn({
            active: false,
            attributes: {
                encode_utf8: false,
                ref_qual_elements: 'parent',
            },
            label: 'Rejection goto',
            referenceTable: 'task',
            referenceQual: "javascript:gs.include('DeliveryTask');new DeliveryTask().getLocalReferenceQual();",
        }),
        short_description: StringColumn({
            attributes: {
                knowledge_search: true,
                no_truncate: true,
                ts_weight: '10',
            },
            dropdown: 'suggestion',
            label: 'Short description',
            maxLength: 160,
        }),
        company: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Company',
            referenceTable: 'core_company',
            referenceQual: 'customer=true',
        }),
        parent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Parent',
            referenceTable: 'task',
            referenceFloats: true,
        }),
        priority: IntegerColumn({
            default: '4',
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Sequence in which an Incident or Problem needs to be resolved, based on impact and urgency',
                    label: 'Priority',
                    plural: 'Priorities',
                    language: 'en',
                },
            ],
        }),
        service_offering: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Service offering',
            referenceTable: 'service_offering',
            referenceQual: "javascript:'parent='+current.business_service;",
        }),
        delivery_task: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Delivery task',
            referenceTable: 'sc_cat_item_delivery_task',
        }),
        delivery_plan: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Delivery plan',
            referenceTable: 'sc_cat_item_delivery_plan',
        }),
        expected_start: DateTimeColumn({
            attributes: {
                timeDimension: true,
            },
            label: 'Expected start',
        }),
        upon_approval: StringColumn({
            default: 'proceed',
            dropdown: 'dropdown_with_none',
            label: 'Upon approval',
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
            spellCheck: true,
        }),
        approval: StringColumn({
            default: 'not requested',
            dropdown: 'dropdown_without_none',
            label: 'Approval',
        }),
        calendar_duration: DurationColumn({
            label: [
                {
                    hint: 'Time elapsed before task was closed',
                    label: 'Duration',
                    plural: 'Durations',
                    language: 'en',
                },
            ],
            maxLength: 40,
            readOnly: true,
        }),
        knowledge: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If checked, will automatically create a Draft knowledge article upon closure',
                    label: 'Knowledge',
                    plural: 'Knowledges',
                    language: 'en',
                },
            ],
        }),
        correlation_display: StringColumn({
            label: 'Correlation display',
            maxLength: 100,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        approval_set: DateTimeColumn({
            attributes: {
                timeDimension: true,
            },
            label: 'Approval set',
        }),
        opened_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            default: 'javascript:gs.getUserID()',
            label: 'Opened by',
            referenceTable: 'sys_user',
            referenceFloats: true,
        }),
        contact_type: StringColumn({
            attributes: {
                no_text_index: true,
            },
            dropdown: 'dropdown_with_none',
            label: 'Contact type',
        }),
        made_sla: BooleanColumn({
            default: true,
            label: 'Made SLA',
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        close_notes: StringColumn({
            label: 'Close notes',
            maxLength: 4000,
            spellCheck: true,
        }),
        reassignment_count: IntegerColumn({
            default: '0',
            label: 'Reassignment count',
        }),
        due_date: DateTimeColumn({
            label: [
                {
                    hint: 'Expected date from assigned to',
                    label: 'Due date',
                    plural: 'Due dates',
                    language: 'en',
                },
            ],
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        impact: IntegerColumn({
            default: '3',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Measure of the business criticality of the affected service',
                    label: 'Impact',
                    plural: 'Impact',
                    language: 'en',
                },
            ],
        }),
        closed_at: DateTimeColumn({
            attributes: {
                sla_closure: 'incident',
                timeDimension: true,
            },
            label: 'Closed',
        }),
        group_list: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Interested groups',
                    label: 'Group list',
                    plural: 'Group lists',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user_group',
        }),
        activity_due: DueDateColumn({
            label: [
                {
                    hint: 'Date by which the Inactivity Monitor expects the task to be updated',
                    label: 'Activity due',
                    plural: 'Activity dues',
                    language: 'en',
                },
            ],
        }),
        comments_and_work_notes: GenericColumn({
            columnType: 'journal_list',
            dependent: 'comments,work_notes',
            label: [
                {
                    hint: 'Combined output of Additional comments and Work notes',
                    label: 'Comments and Work notes',
                    plural: 'Comments and Work notes',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        contract: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ref_ac_columns: 'short_description',
                ref_auto_completer: 'AJAXTableCompleter',
            },
            label: 'Contract',
            referenceTable: 'ast_contract',
            referenceQual: 'javascript:contractFilter();',
        }),
        sn_ai_sentiment: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Sentiment',
            readOnly: true,
            referenceTable: 'sys_sentiment_details',
        }),
        route_reason: IntegerColumn({
            dropdown: 'dropdown_with_none',
            label: 'Transfer reason',
            readOnly: true,
        }),
        task_effective_number: StringColumn({
            attributes: {
                ignore_filter_on_new: true,
                no_text_index: true,
            },
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: 'current.universal_request.nil() ? current.number: current.universal_request.number',
            },
            label: 'Effective number',
            readOnly: true,
        }),
        universal_request: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'none',
            label: 'Universal Request',
            referenceTable: 'task',
            referenceQual: "javascript:'sys_class_name=universal_request'",
        }),
        comments: GenericColumn({
            columnType: 'journal_input',
            label: [
                {
                    hint: 'Journaled field, shared with the end user',
                    label: 'Additional comments',
                    plural: 'Additional comments',
                    language: 'en',
                },
            ],
            maxLength: 4000,
            spellCheck: true,
        }),
        urgency: IntegerColumn({
            default: '3',
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Measure of the business criticality based on the impact and on the business needs of the Customer',
                    label: 'Urgency',
                    plural: 'Urgencies',
                    language: 'en',
                },
            ],
        }),
        assigned_to: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            dependent: 'assignment_group',
            label: [
                {
                    hint: 'Person primarily responsible for working this task',
                    label: 'Assigned to',
                    plural: 'Assigned to',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
            referenceFloats: true,
            referenceQual: 'roles=itil',
        }),
        number: StringColumn({
            attributes: {
                ignore_filter_on_new: true,
                ts_weight: '50',
            },
            default: 'javascript:getNextObjNumberPadded();',
            label: 'Number',
        }),
        cmdb_ci: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ref_ac_columns: 'sys_class_name',
                ref_auto_completer: 'AJAXTableCompleter',
                ref_contributions: 'task_show_ci_map;show_related_records',
            },
            dependent: 'company',
            label: [
                {
                    hint: 'Item or service affected',
                    label: 'Configuration item',
                    plural: 'Configuration items',
                    language: 'en',
                },
            ],
            referenceTable: 'cmdb_ci',
            referenceQual:
                "javascript: ['incident', 'problem'].indexOf(current.sys_class_name + '') == -1? '' : 'operational_statusNOT IN' + new OpsStatusFilter('cmdb_ci').by('CreateTask').join()",
        }),
        active: BooleanColumn({
            attributes: {
                ignore_filter_on_new: true,
            },
            default: true,
            label: 'Active',
        }),
        state: IntegerColumn({
            default: '1',
            dropdown: 'dropdown_without_none',
            label: 'State',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        opened_at: DateTimeColumn({
            attributes: {
                sla_basis: 'incident',
                timeDimension: true,
            },
            default: 'javascript:gs.nowDateTime()',
            label: 'Opened',
        }),
        watch_list: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Interested users',
                    label: 'Watch list',
                    plural: 'Watch lists',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        sla_due: DueDateColumn({
            label: [
                {
                    hint: 'Date by which the SLA expects this task to be completed',
                    label: 'SLA due',
                    plural: 'SLA dues',
                    language: 'en',
                },
            ],
        }),
        escalation: IntegerColumn({
            default: '0',
            dropdown: 'dropdown_without_none',
            label: 'Escalation',
            readOnly: true,
        }),
        time_worked: GenericColumn({
            columnType: 'timer',
            label: 'Time worked',
        }),
        additional_assignee_list: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Additional assignees',
                    label: 'Additional assignee list',
                    plural: 'Additional assignee lists',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        correlation_id: StringColumn({
            label: 'Correlation ID',
            maxLength: 100,
        }),
        approval_history: GenericColumn({
            columnType: 'journal',
            label: 'Approval history',
            maxLength: 4000,
            spellCheck: true,
        }),
        business_duration: DurationColumn({
            label: [
                {
                    hint: 'Business time elapsed before task was closed',
                    label: 'Business duration',
                    plural: 'Business durations',
                    language: 'en',
                },
            ],
            maxLength: 40,
            readOnly: true,
        }),
        location: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                tree_picker: true,
            },
            dependent: 'company',
            label: [
                {
                    hint: 'Where the caller or service is located',
                    label: 'Location',
                    plural: 'Locations',
                    language: 'en',
                },
            ],
            referenceTable: 'cmn_location',
        }),
        user_input: GenericColumn({
            columnType: 'user_input',
            label: 'User input',
            maxLength: 4000,
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        work_notes: GenericColumn({
            columnType: 'journal_input',
            label: 'Work notes',
            maxLength: 4000,
            spellCheck: true,
        }),
        closed_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Closed by',
            referenceTable: 'sys_user',
            referenceFloats: true,
        }),
        follow_up: DateTimeColumn({
            label: 'Follow up',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the task belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
    },
    textIndex: true,
})
